cases.query:
EVALUATE CALCULATETABLE(
    SUMMARIZECOLUMNS('Date'[Year Month], "Total Sales", [Total Sales], "Target", [Target]),
    NOT ('Orders'[Status] IN {"Cancelled"}),
    'Date'[Year] IN {2025}
)

EVALUATE CALCULATETABLE(
    SUMMARIZECOLUMNS('Stores'[Store Name], 'Stores'[Store Manager], 'Stores'[City], "Total Sales", [Total Sales]),
    'Stores'[Channel] IN {"Retail", "Outlet"},
    'Stores'[Region] IN {"East"}
)

EVALUATE CALCULATETABLE(
    SUMMARIZECOLUMNS(ROLLUPADDISSUBTOTAL('Returns'[Reason], "IsTotal"), "Returns Count", [Returns Count], "Refunds", [Refunds]),
    'Stores'[Channel] IN {"Retail", "Outlet"},
    'Stores'[Region] IN {"East"}
)

EVALUATE CALCULATETABLE(
    SUMMARIZECOLUMNS('Customers'[Customer Name], "Total Sales", [Total Sales]),
    'Stores'[Channel] IN {"Online"},
    'Web Sessions'[Device] IN {"Mobile"},
    'Customers'[Segment] IN {"Corporate"}
)

EVALUATE CALCULATETABLE(
    SUMMARIZECOLUMNS(ROLLUPADDISSUBTOTAL('Customers'[Loyalty Tier], "IsTotal"), "Total Sales", [Total Sales]),
    'Stores'[Channel] IN {"Online"},
    'Web Sessions'[Device] IN {"Mobile"},
    'Customers'[Segment] IN {"Corporate"}
)
